-- Limpeza opcional para reexecutar o script durante testes.
DROP TABLE IF EXISTS item_orcado;
DROP TABLE IF EXISTS item;
DROP TABLE IF EXISTS subgrupo_servico;
DROP TABLE IF EXISTS grupo_servico;
DROP TABLE IF EXISTS obra;

-- 1. Tabela raiz: obra/contrato.
CREATE TABLE obra (
    obra_codigo VARCHAR(20) PRIMARY KEY,
    obra_nome TEXT NOT NULL,
    bdi_percentual NUMERIC(6,2)
);

-- 2. Grupo de serviço (nível 1 da hierarquia orçamentária).
CREATE TABLE grupo_servico (
    grupo_codigo VARCHAR(20) PRIMARY KEY,
    grupo_nome TEXT NOT NULL
);

-- 3. Subgrupo de serviço, pertencente a um grupo (nível 2).
CREATE TABLE subgrupo_servico (
    subgrupo_codigo VARCHAR(20) PRIMARY KEY,
    subgrupo_nome TEXT NOT NULL,
    grupo_codigo VARCHAR(20) NOT NULL REFERENCES grupo_servico(grupo_codigo)
);

-- 4. Catálogo de itens/serviços (nível 3, o item em si).
CREATE TABLE item (
    item_codigo VARCHAR(30) PRIMARY KEY,
    tipo VARCHAR(20),
    descricao TEXT NOT NULL,
    unidade VARCHAR(20),
    valor_unitario NUMERIC(14,2)
);

-- 5. Item orçado: fato que liga obra + subgrupo + item com quantidade e valores.
CREATE TABLE item_orcado (
    id_item_orcado INTEGER PRIMARY KEY,
    obra_codigo VARCHAR(20) NOT NULL REFERENCES obra(obra_codigo),
    subgrupo_codigo VARCHAR(20) NOT NULL REFERENCES subgrupo_servico(subgrupo_codigo),
    item_codigo VARCHAR(30) NOT NULL REFERENCES item(item_codigo),
    quantidade NUMERIC(14,3) NOT NULL,
    valor_unitario_ajustado NUMERIC(14,2),
    valor_total NUMERIC(16,2)
);

